<?php
declare(strict_types=1);ob_start();$root=dirname(__DIR__,2);require$root.'/tests/bootstrap.php';helper(['general','date_time','currency']);$db=require$root.'/tests/Increment02/isolated_database.php';use App\Services\WarehouseMovementService;use App\Services\WarehouseStockService;$p=$f=0;$ok=function($v,$m)use(&$p,&$f){echo($v?'[PASS] ':'[FAIL] ').$m.PHP_EOL;$v?$p++:$f++;};$now=get_current_utc_time();$actor=(int)$db->table('users')->where('deleted',0)->get(1)->getRow()->id;
$db->table('warehouses')->insert(['name'=>'Almacén León Test','code'=>'LEON-'.substr(uniqid(),-6),'status'=>'active','created_by'=>$actor,'created_at'=>$now,'updated_at'=>$now,'deleted'=>0]);$wid=(int)$db->insertID();$db->table('warehouse_products')->insert(['name'=>'Zapato 750 Negro T28','internal_code'=>'DOLD-ZAP-'.uniqid(),'barcode'=>'750'.random_int(1000000000,9999999999),'control_unit'=>'PAR','status'=>'active','created_by'=>$actor,'created_at'=>$now,'updated_at'=>$now,'deleted'=>0]);$pid=(int)$db->insertID();$ok($wid>0&&$pid>0,'crea almacén y producto logístico independiente');$itemsBefore=$db->table('items')->countAllResults();$proposalBefore=$db->table('proposal_items')->countAllResults();$fiscalBefore=$db->table('fiscal_documents')->countAllResults();
$svc=new WarehouseMovementService($db);$stock=new WarehouseStockService($db);$entry=$svc->createDraft(['movement_type'=>'ENTRY','warehouse_id'=>$wid,'movement_date'=>'2026-08-29 10:00','reference_type'=>'EXTERNO','reference_text'=>'Carga inicial','lines'=>[['warehouse_product_id'=>$pid,'quantity'=>'100']]],$actor);$ok($stock->getStock($pid,$wid)==='0.000000','borrador no afecta existencia');$svc->confirm($entry,$actor);$ok($stock->getStock($pid,$wid)==='100.000000','entrada confirmada suma 100');$exit=$svc->createDraft(['movement_type'=>'EXIT','warehouse_id'=>$wid,'movement_date'=>'2026-08-29 11:00','lines'=>[['warehouse_product_id'=>$pid,'quantity'=>'30']]],$actor);$svc->confirm($exit,$actor);$ok($stock->getStock($pid,$wid)==='70.000000','salida confirmada deja 70');
$bad=$svc->createDraft(['movement_type'=>'EXIT','warehouse_id'=>$wid,'movement_date'=>'2026-08-29 12:00','lines'=>[['warehouse_product_id'=>$pid,'quantity'=>'80']]],$actor);$blocked=false;try{$svc->confirm($bad,$actor);}catch(InvalidArgumentException$e){$blocked=str_contains($e->getMessage(),'Disponible: 70.000000');}$ok($blocked&&$stock->getStock($pid,$wid)==='70.000000','salida insuficiente se revierte sin cambiar stock');$adjust=$svc->createDraft(['movement_type'=>'ADJUSTMENT','warehouse_id'=>$wid,'movement_date'=>'2026-08-29 13:00','lines'=>[['warehouse_product_id'=>$pid,'physical_quantity'=>'68']]],$actor);$svc->confirm($adjust,$actor);$ok($stock->getStock($pid,$wid)==='68.000000','ajuste físico genera delta -2');$k=$stock->kardex($pid,$wid);$ok(array_column($k,'balance')===['100.000000','70.000000','68.000000'],'kardex reconstruye 100, 70, 68');$ok(array_column($k,'quantity_delta')===['100.000000','-30.000000','-2.000000'],'ledger conserva deltas canónicos');
$svc->confirm($adjust,$actor);$ok($stock->getStock($pid,$wid)==='68.000000','confirmación repetida es idempotente');$db->table('warehouse_products')->where('id',$pid)->update(['status'=>'inactive']);$ok($stock->getStock($pid,$wid)==='68.000000','inactivar producto conserva movimientos');$db->table('warehouses')->where('id',$wid)->update(['status'=>'inactive']);$ok($stock->getStock($pid,$wid)==='68.000000','inactivar almacén conserva movimientos');$ok($db->table('items')->countAllResults()===$itemsBefore&&$db->table('proposal_items')->countAllResults()===$proposalBefore&&$db->table('fiscal_documents')->countAllResults()===$fiscalBefore,'movimientos no modifican productos comerciales, propuestas ni CFDI');
$migration=file_get_contents($root.'/app/Database/Migrations/2026-08-29-130000_CreateWarehouseLogisticsFoundation.php');$service=file_get_contents($root.'/app/Services/WarehouseMovementService.php');$public=implode('',array_map('file_get_contents',glob($root.'/app/Views/proposals/*.php')));$ok(str_contains($service,'FOR UPDATE')&&str_contains($service,'transBegin'),'confirmación usa transacción y bloqueo');$ok(str_contains($migration,"'quantity_delta'=>['type'=>'DECIMAL'")&&!str_contains($migration,'commercial_item_id'),'cantidad es decimal y no acopla items comerciales');$ok(!str_contains($public,'warehouse_products')&&!str_contains($public,'warehouse_movements'),'dominio logístico no aparece en propuestas');echo"TOTAL PASS=$p FAIL=$f".PHP_EOL;$out=ob_get_clean();echo$out;exit($f?1:0);
